\set ON_ERROR_STOP on
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(command text,expected text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>expected then raise exception 'FAIL: % expected % got % (%)',label,expected,sqlstate,sqlerrm;end if;raise notice 'PASS: %',label;return;end;raise exception 'FAIL: % unexpectedly succeeded',label;end;$$;
create function pg_temp.base(a text default 'create') returns jsonb language sql as $$select jsonb_build_object('action',a,'schedule_id','82000000-0000-0000-0000-000000000001','schedule_revision',(select revision from public.rota_schedules where id='82000000-0000-0000-0000-000000000001'))$$;
create function pg_temp.recipe(n text default 'Morning') returns jsonb language sql as $$select jsonb_build_object('name',n,'title','Site cover','job_id','84000000-0000-0000-0000-000000000001','start_minute',480,'end_minute',960,'end_day_offset',0)$$;
create function pg_temp.target(n text default 'Morning') returns jsonb language sql as $$select jsonb_build_object('template_id',id,'template_revision',revision) from public.rota_shift_templates where name=n and deleted_at is null order by id limit 1$$;
create function pg_temp.apply_date(d text,n text default 'Morning',worker text default '83000000-0000-0000-0000-000000000001') returns jsonb language sql as $$select pg_temp.base('apply')||pg_temp.target(n)||jsonb_build_object('agent_id',worker,'date',d,'start_occurrence','','end_occurrence','','allow_overlap',false)$$;
create function pg_temp.save(c jsonb,op uuid default gen_random_uuid()) returns jsonb language sql as $$select public.save_rota_template('81000000-0000-0000-0000-000000000001',op,c::text)$$;
select pg_temp.check_true((select bool_and(relrowsecurity) from pg_class where oid in('public.rota_shift_templates'::regclass,'public.rota_template_audit'::regclass,'workforce_private.rota_template_operations'::regclass)),'all new tables use RLS');
select pg_temp.check_true(not has_table_privilege('anon','public.rota_shift_templates','SELECT') and not has_table_privilege('authenticated','public.rota_shift_templates','INSERT') and not has_table_privilege('authenticated','workforce_private.rota_template_operations','SELECT'),'browser grants do not expose writes or receipts');
select pg_temp.check_true(not has_function_privilege('anon','public.save_rota_template(uuid,uuid,text)','EXECUTE') and not has_function_privilege('service_role','public.save_rota_template(uuid,uuid,text)','EXECUTE'),'mutation RPC authenticated only');
select pg_temp.check_true((select bool_and(not prosecdef and proconfig=array['search_path=""']) from pg_proc where oid in('public.save_rota_template(uuid,uuid,text)'::regprocedure,'public.read_rota_templates(uuid,uuid,text,integer,jsonb)'::regprocedure,'public.reconcile_rota_template_operation(uuid,uuid,text,uuid,uuid)'::regprocedure)),'public wrappers are empty-path invokers');
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000901',false);
select pg_temp.check_true(pg_temp.save(pg_temp.base()||pg_temp.recipe())->>'template_revision'='1','owner creates recipe');
select pg_temp.check_true((select revision=2 from public.rota_schedules where id='82000000-0000-0000-0000-000000000001'),'template creation advances schedule revision');
select pg_temp.check_true(jsonb_array_length(public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001')->'templates')=1,'owner reads private template list');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base()||pg_temp.recipe()||'{"unexpected":true}')$q$,'22023','unknown fields rejected');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base()||pg_temp.recipe()||'{"start_minute":true}')$q$,'22023','typed minute rejected');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base()||pg_temp.recipe()||'{"end_minute":400}')$q$,'22023','nonpositive wall recipe rejected');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base()||pg_temp.recipe()||'{"job_id":"84000000-0000-0000-0000-000000000002"}')$q$,'23503','foreign job rejected');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base()||pg_temp.recipe()||'{"schedule_revision":1}')$q$,'40001','stale schedule rejected');
select pg_temp.expect_error($q$select public.save_rota_template('81000000-0000-0000-0000-000000000001',gen_random_uuid(),'{"action":"create","action":"create"}')$q$,'22023','duplicate JSON fields rejected');
select pg_temp.check_true(pg_temp.save(pg_temp.base('duplicate')||pg_temp.target()||'{"name":"Second"}')->>'template_revision'='1','duplicate creates new recipe revision');
select pg_temp.check_true(pg_temp.save(pg_temp.base('edit')||pg_temp.target('Second')||pg_temp.recipe('Second')||'{"title":"Updated cover"}')->>'template_revision'='2','edit increments template revision');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base('delete')||pg_temp.target('Second')||'{"template_revision":1}')$q$,'40001','stale recipe rejected');
select pg_temp.check_true(pg_temp.save(pg_temp.base('delete')||pg_temp.target('Second'))->>'template_revision'='3','delete retains tombstone revision');
select pg_temp.check_true((public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001')->'page'->>'total')::integer=1,'deleted template absent from list');
select pg_temp.check_true(pg_temp.save(pg_temp.apply_date('2026-11-01'))->>'shift_id' is not null,'apply creates named draft');
select pg_temp.check_true((select count(*)=1 and bool_and(status='draft' and title='Site cover' and starts_at='2026-11-01T08:00Z'::timestamptz) from public.rota_shifts where title='Site cover'),'draft stores server computed time and title');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.apply_date('2026-11-01'))$q$,'P0001','overlap requires acknowledgement');
select pg_temp.check_true(pg_temp.save(pg_temp.apply_date('2026-11-01')||'{"allow_overlap":true}')->>'shift_id' is not null,'explicit overlap accepted');
select pg_temp.check_true(pg_temp.save(pg_temp.apply_date('2026-11-02','Morning','83000000-0000-0000-0000-000000000002'))->>'shift_id' is not null,'directory-only worker applies without Auth provisioning');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.apply_date('2026-02-30'))$q$,'22008','invalid calendar date rejected');
-- Store operation payload in a session-local table to replay the exact original bytes.
create temp table pending(c jsonb,op uuid);insert into pending values(pg_temp.base()||pg_temp.recipe('Idempotent'),'85000000-0000-0000-0000-000000000001');
select pg_temp.check_true((select pg_temp.save(c,op)->>'action'='create' from pending),'UUID action recorded');
select pg_temp.check_true((select pg_temp.save(c,op)->>'template_revision'='1' from pending),'same UUID payload replay ignores old revision');
select pg_temp.check_true((select count(*)=1 from public.rota_shift_templates where name='Idempotent'),'replay creates only one recipe');
select pg_temp.expect_error($q$select pg_temp.save(c||'{"name":"Changed"}',op) from pending$q$,'40001','UUID payload alteration rejected');
select pg_temp.check_true(public.reconcile_rota_template_operation('81000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000001','create','82000000-0000-0000-0000-000000000001',null)->>'status'='recorded','original actor gets recorded recovery');
select pg_temp.check_true(public.reconcile_rota_template_operation('81000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000002','create','82000000-0000-0000-0000-000000000001',null)->>'status'='not_recorded','absent recovery closes UUID');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.base()||pg_temp.recipe('Too late'),'85000000-0000-0000-0000-000000000002')$q$,'40001','closed absent blocks delayed write');
select pg_temp.expect_error($q$select public.reconcile_rota_template_operation('81000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000001','apply','82000000-0000-0000-0000-000000000001',(pg_temp.target()->>'template_id')::uuid)$q$,'40001','recovery action cannot change');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000903',false);
select pg_temp.check_true(pg_temp.save(pg_temp.base()||pg_temp.recipe('Delegated'))->>'action'='create','delegated manager creates');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000902',false);
select pg_temp.check_true(pg_temp.save(pg_temp.base()||pg_temp.recipe('Admin'))->>'action'='create','admin creates');
select pg_temp.check_true(public.reconcile_rota_template_operation('81000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000001','create','82000000-0000-0000-0000-000000000001',null)->>'status'='not_recorded','another authorized actor cannot recover original receipt');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000905',false);
select pg_temp.expect_error($q$select public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001')$q$,'42501','undelegated manager denied list');
select pg_temp.expect_error($q$select pg_temp.save('{"action":"create","schedule_id":"82000000-0000-0000-0000-000000000001","schedule_revision":1}'||pg_temp.recipe())$q$,'42501','undelegated manager denied mutation');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000904',false);
select pg_temp.check_true((select count(*)=0 from public.rota_shift_templates),'employee direct read gets no recipes');
select pg_temp.check_true((select count(*)=0 from public.rota_shifts where title='Site cover'),'employee cannot read template drafts');
select pg_temp.expect_error($q$select public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001')$q$,'42501','employee denied RPC');
select pg_temp.expect_error($q$insert into public.rota_shift_templates(tenant_id,schedule_id,name,title,job_id,start_minute,end_minute,end_day_offset,creator_user_id) values('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','Fake','','84000000-0000-0000-0000-000000000001',480,960,0,auth.uid())$q$,'42501','direct browser writes denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000906',false);
select pg_temp.expect_error($q$select public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001')$q$,'42501','foreign owner denied list');
reset role;
-- Database timezone correctness independent of frontend.
select pg_temp.check_true(workforce_private.rota_template_instant('2026-07-01 08:00','Europe/London','')='2026-07-01 07:00Z'::timestamptz,'wall time follows schedule summer zone');
select pg_temp.check_true(workforce_private.rota_template_instant('2026-01-01 08:00','Asia/Kathmandu','')='2026-01-01 02:15Z'::timestamptz,'fractional-offset zone supported');
select pg_temp.expect_error($q$select workforce_private.rota_template_instant('2026-03-29 01:30','Europe/London','')$q$,'22007','spring gap roundtrip rejected');
select pg_temp.expect_error($q$select workforce_private.rota_template_instant('2026-10-25 01:30','Europe/London','')$q$,'22008','fall fold requires selection');
select pg_temp.check_true(workforce_private.rota_template_instant('2026-10-25 01:30','Europe/London','earlier')='2026-10-25 00:30Z'::timestamptz,'fold earlier is exact');
select pg_temp.check_true(workforce_private.rota_template_instant('2026-10-25 01:30','Europe/London','later')='2026-10-25 01:30Z'::timestamptz,'fold later is exact');
select pg_temp.expect_error($q$select workforce_private.rota_template_instant('2011-12-30 10:00','Pacific/Apia','')$q$,'22007','skipped calendar day rejected');
select pg_temp.expect_error($q$select workforce_private.rota_template_instant('2026-01-01 08:00','Factory','')$q$,'22023','special unsupported zone rejected');
select pg_temp.check_true(workforce_private.rota_template_instant('2026-04-05 01:45','Australia/Lord_Howe','later')-workforce_private.rota_template_instant('2026-04-05 01:45','Australia/Lord_Howe','earlier')=interval '30 minutes','half-hour fold is handled');
-- Apply validates DST at the database boundary, rather than accepting frontend instants.
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000901',false);
select pg_temp.save(pg_temp.base()||pg_temp.recipe('Night')||'{"start_minute":1380,"end_minute":420,"end_day_offset":1}');
