select pg_temp.save(pg_temp.base()||pg_temp.recipe('Gap')||'{"start_minute":90,"end_minute":180}');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.apply_date('2026-03-29','Gap'))$q$,'22007','apply cannot coerce spring gap');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.apply_date('2026-10-25','Gap'))$q$,'22008','apply fold requires explicit choice');
select pg_temp.check_true(pg_temp.save(pg_temp.apply_date('2026-10-25','Gap')||'{"start_occurrence":"later"}')->>'shift_id' is not null,'apply honors later fold choice');
select pg_temp.save(pg_temp.base()||pg_temp.recipe('Full day')||'{"end_minute":480,"end_day_offset":1}');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.apply_date('2026-10-24','Full day'))$q$,'23514','apply rejects 25 elapsed hours');
select pg_temp.check_true(pg_temp.save(pg_temp.apply_date('2026-03-28','Full day'))->>'shift_id' is not null,'apply accepts 23-hour local day');
select pg_temp.save(pg_temp.base()||pg_temp.recipe('Two midnights')||'{"start_minute":1410,"end_minute":30,"end_day_offset":2}');
select pg_temp.check_true(pg_temp.save(pg_temp.apply_date('2026-03-28','Two midnights')||'{"allow_overlap":true}')->>'shift_id' is not null,'offset two preserves 24 elapsed hours through spring transition');
select pg_temp.expect_error($q$select pg_temp.save(pg_temp.apply_date('2026-11-20','Morning','83000000-0000-0000-0000-000000000099'))$q$,'23503','missing worker denied');
create temp table applied_pending(c jsonb,op uuid);insert into applied_pending values(pg_temp.apply_date('2026-11-22'),'85000000-0000-0000-0000-000000000010');
