-- Populated pagination, literal search, scope and revision fences.
insert into public.rota_shift_templates(tenant_id,schedule_id,name,title,job_id,start_minute,end_minute,end_day_offset,creator_user_id) select '81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','Page '||lpad(n::text,3,'0'),'','84000000-0000-0000-0000-000000000001',480,960,0,'00000000-0000-0000-0000-000000000901' from generate_series(1,105)n;
insert into public.rota_shift_templates(tenant_id,schedule_id,name,title,job_id,start_minute,end_minute,end_day_offset,creator_user_id) values('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','100% coverage','','84000000-0000-0000-0000-000000000001',480,960,0,'00000000-0000-0000-0000-000000000901');
