select pg_temp.check_true((select jsonb_array_length(public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','Page',100,v->'page'->'nextCursor')->'templates')=5 from pages),'keyset returns remaining five');
