select pg_temp.expect_error($q$select public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','Changed',100,v->'page'->'nextCursor') from pages$q$,'40001','cursor filter scope rejected');
select pg_temp.expect_error($q$select public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','',101)$q$,'22023','page cap enforced');
select pg_temp.save(pg_temp.base()||pg_temp.recipe('Changes fence'));
select pg_temp.expect_error($q$select public.read_rota_templates('81000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001','Page',100,v->'page'->'nextCursor') from pages$q$,'40001','schedule revision fences old page');
